export interface WidgetCard {
  id: string;
  title: string;
  excerpt?: string;
  image_url?: string;
  source_label?: string;
  source_url?: string;
  score?: number /* float64 */;
  badges?: WidgetBadge[];
  actions?: WidgetActionDescriptor[];
}
/**
 * WidgetImageVariantsV1 是 image-variants@v1 widget 的数据 schema。
 */
export interface WidgetImageVariantsV1 {
  title?: string;
  primary: WidgetImageItem;
  variants?: WidgetImageItem[];
  actions?: WidgetActionDescriptor[];
}
/**
 * WidgetImageItem 是单张图片条目。
 * URL 必须为 https；AltText 必填；Width/Height 若非 0 必须 > 0。
 */
export interface WidgetImageItem {
  id: string;
  url: string; // https only
  alt_text: string;
  width?: number /* int */;
  height?: number /* int */;
  caption?: string;
  actions?: WidgetActionDescriptor[];
}
